#if TEST_BUILD
using System;using System.IO;using System.Linq;using System.Threading.Tasks;using System.Windows.Forms;
internal sealed partial class ControlWindow {
 internal async Task RunSubmitSmoke(){FaultHandoffForm dialog=null;bool failed=false;try{
  string catalog=Common.ReadShared(library.FilePath),settings=Common.ReadShared(Path.Combine(Common.Root,"data/settings.json"));var record=FaultHandoffForm.Demo();
  dialog=new FaultHandoffForm(record,Write);faultWindow=dialog;dialog.TestSkipClipboard=true;dialog.Show(this);await Task.Delay(150);Require(dialog.TestPackage==null&&dialog.open.Enabled,"Opening form must not bypass optional input or disable folder action");Require(!dialog.TestSummary.Contains("SHA")&&!dialog.TestSummary.Contains("阶段")&&!dialog.TestSummary.Contains("schema"),"Technical details leaked into simple explanation");ClientShot(dialog,"submit-empty");await dialog.TestCopy();var original=dialog.TestPackage;Require(original!=null&&original.ClipboardText.Contains("用户尚未补充"),"Optional empty input required");dialog.Close();faultWindow=null;
  dialog=new FaultHandoffForm(record,Write);faultWindow=dialog;dialog.TestClipboard=text=>false;dialog.Show(this);await dialog.TestCopy();Require(dialog.TestPackage!=null&&dialog.TestPackage.Reused&&dialog.TestPackage.PackageSha256==original.PackageSha256&&dialog.open.Enabled,"Reopen or clipboard busy lost existing package");
  dialog.TestClipboard=null;await dialog.TestCopy();Require(Clipboard.GetText()==dialog.TestPackage.ClipboardText,"Actual clipboard copy mismatch");
  dialog.TestNote("我补充：点击后没有反应");await dialog.TestCopy();Require(dialog.TestPackage.Id!=original.Id&&dialog.TestPackage.ClipboardText.Contains("我补充：")&&File.Exists(Path.Combine(Common.Root,original.PackageRelative)),"Edited note lost/replaced evidence");ClientShot(dialog,"submit-with-note");File.WriteAllText(Path.Combine(Common.Root,"evidence/submit-example.txt"),dialog.TestPackage.ClipboardText);File.Copy(Path.Combine(Common.Root,dialog.TestPackage.PackageRelative),Path.Combine(Common.Root,"evidence/submit-example.zip"));dialog.Close();faultWindow=null;
  // Verify the actual folder handler target, without launching Explorer in automated tests.
  dialog=new FaultHandoffForm(record,Write);dialog.TestSkipClipboard=true;string folderTarget=null;dialog.TestFolderLauncher=path=>folderTarget=path;dialog.Show(this);await dialog.TestFolder();Require(dialog.TestPackage!=null&&File.Exists(folderTarget)&&Path.GetDirectoryName(folderTarget)==DiagnosticBundle.Root,"Folder-before-copy failed to prepare/select evidence");dialog.Close();
  Require(Common.ReadShared(library.FilePath)==catalog&&Common.ReadShared(Path.Combine(Common.Root,"data/settings.json"))==settings&&CurrentRun==null,"Submit flow modified data or started playback");
  Common.SaveNew(Path.Combine(Common.Root,"evidence/submit-ui-result.json"),new{passed=true,noAutomaticCopyOnOpen=true,optionalBlankAccepted=true,noteIncluded=true,reopenExistingVerifiedPackage=true,busyClipboardKeepsFolderAvailable=true,actualClipboardChecked=true,noteChangeNewLinkedPackage=true,simpleVisibleCopy=true,folderTargetChecked=true,folderBeforeCopyPreparesEvidence=true,explorerLaunchedByInternalTest=false,dataPreserved=true,playerStarted=false,userClicked=false});
 }catch(Exception ex){failed=true;Common.SaveNew(Path.Combine(Common.Root,"evidence/submit-ui-failed.json"),new{error=ex.ToString()});}if(failed&&dialog!=null&&!dialog.IsDisposed)await dialog.StopForOwner();faultWindow=null;Close();}
}
#endif
